class Solution {
public:
    int maximumNumberOfStringPairs(vector<string>& words) {
        bool seen[26][26] = {{false}};
        int count = 0;
        for (const string& w : words) {
            int a = w[0] - 'a';
            int b = w[1] - 'a';
            if (seen[b][a]) {
                count++;
            } else {
                seen[a][b] = true;
            }
        }
        return count;
    }
};
